const readline = require('readline');

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

rl.question('Enter a string of text: ', (inputString) => {
  const words = inputString.split(' ');
  const reversedWords = words.reverse();
  const encryptedWords = reversedWords.map(word => word.split('').reverse().join(''));
  let encryptedString = '';

  for (let i = 0; i < encryptedWords.length; i++) {
    encryptedString += encryptedWords[i].charAt(0) + encryptedWords[i].substring(1);
    if (i < encryptedWords.length - 1) {
      encryptedString += ' ';
    }
  }

  console.log('Encrypted string:', encryptedString);
  rl.close();
});
```

